bool Manifold::Impl::IsDuplicated(const int edge) const {
  const int endVert = halfedge_.End(edge);
  bool duplicated = false;
  ForVert(edge, [&](int current) {
    if (current != edge && halfedge_.End(current) == endVert) duplicated = true;
  });
